package com.example.jsonapp;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

public final class JsonMapperFactory {

    private JsonMapperFactory() {
    }

    public static ObjectMapper create() {
        return JsonMapper.builder()
                .addModule(new JavaTimeModule())
                .build();
    }
}

package com.example.jsonapp.model;

import java.time.Instant;
import java.util.List;

public record Person(
        long id,
        String name,
        String email,
        Instant createdAt,
        List<String> roles) {
}

package com.example.jsonapp;

import com.example.jsonapp.model.Person;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.time.Instant;
import java.util.List;

public final class Main {

    public static void main(String[] args) throws Exception {
        ObjectMapper mapper = JsonMapperFactory.create();

        Person person = new Person(
                1L,
                "Ada Lovelace",
                "ada@example.com",
                Instant.parse("2026-01-01T00:00:00Z"),
                List.of("admin", "user"));

        String json = mapper
                .writerWithDefaultPrettyPrinter()
                .writeValueAsString(person);
        System.out.println("Generated JSON:");
        System.out.println(json);

        Person parsed = mapper.readValue(json, Person.class);
        System.out.println("Parsed back: " + parsed);
    }
}

package com.example.jsonapp;

import com.example.jsonapp.model.Person;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

import java.time.Instant;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;

class JsonRoundTripTest {

    private final ObjectMapper mapper = JsonMapperFactory.create();

    @Test
    void generatesAndParsesJson() throws Exception {
        Person original = new Person(
                1L,
                "Ada Lovelace",
                "ada@example.com",
                Instant.parse("2026-01-01T00:00:00Z"),
                List.of("admin", "user"));

        String json = mapper.writeValueAsString(original);
        Person parsed = mapper.readValue(json, Person.class);

        assertEquals(original, parsed);
    }
}

